   [158]={next_id=159, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="否则我也不会这么多年都不回家，总是让琳梅尔阿姨代替我照顾他了。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
